<?php
namespace App\Domain\Clients; use App\Models\Client; use Illuminate\Support\Facades\DB; final class ClientRelationManager { public function sync(Client $item,array $solutions,array $products,array $capabilities,array $pages):void{DB::transaction(function()use($item,$solutions,$products,$capabilities,$pages){foreach([[$item->relatedSolutions(),$solutions],[$item->relatedProducts(),$products],[$item->relatedCapabilities(),$capabilities],[$item->relatedPages(),$pages]] as [$relation,$ids]){$relation->sync(collect($ids)->values()->mapWithKeys(fn($id,$i)=>[$id=>['display_order'=>$i+1]])->all());}});} }
